[CmdletBinding()]
param([int]$ProjectCount=10,[int]$FindingsPerProject=5000,[int]$ConcurrentReaders=64,[int]$ConcurrentWriters=32,[int]$ReadRequests=500,[int]$WriteRequests=200)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path
foreach($c in 'git','dotnet','docker'){if(-not(Get-Command $c -ErrorAction SilentlyContinue)){throw "$c is required."}}
function Get-FreePort{$l=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback,0);$l.Start();$p=([Net.IPEndPoint]$l.LocalEndpoint).Port;$l.Stop();$p}
function Get-P95([double[]]$v){if(!$v.Count){return 0};$s=@($v|Sort-Object);[Math]::Round($s[[Math]::Max(0,[Math]::Ceiling($s.Count*.95)-1)],3)}
function Wait-Http($u){$d=(Get-Date).AddSeconds(120);do{try{if((Invoke-WebRequest -UseBasicParsing $u -TimeoutSec 3).StatusCode-eq200){return}}catch{};Start-Sleep -Milliseconds 400}while((Get-Date)-lt$d);throw "Timed out waiting for $u"}
function Wait-HttpBatch([System.Collections.ArrayList]$pending,[System.Collections.Generic.List[double]]$latencies,[System.Collections.Generic.List[string]]$errors){
 while($pending.Count-gt0){for($i=$pending.Count-1;$i-ge0;$i--){$entry=$pending[$i];if(!$entry.Task.IsCompleted){continue};$entry.Stopwatch.Stop();$latencies.Add($entry.Stopwatch.Elapsed.TotalMilliseconds);try{$response=$entry.Task.GetAwaiter().GetResult();if(-not$response.IsSuccessStatusCode){$errors.Add("$($entry.Kind):$([int]$response.StatusCode)")};$response.Dispose()}catch{$errors.Add("$($entry.Kind)-ex:$($_.Exception.Message)")};if($entry.Content){$entry.Content.Dispose()};$pending.RemoveAt($i)};if($pending.Count-gt0){Start-Sleep -Milliseconds 2}}
}
$out=Join-Path $root 'artifacts\governance-load';New-Item -ItemType Directory -Force $out|Out-Null;Remove-Item (Join-Path $out 'GOVERNANCE_LOAD_PASS.txt') -Force -ErrorAction SilentlyContinue
$stamp=Get-Date -Format 'yyyyMMddHHmmss';$compose="dip-govload-$stamp";$pgPort=Get-FreePort;$apiPort=Get-FreePort;$api=$null;$vars='POSTGRES_PORT','POSTGRES_DB','POSTGRES_USER','POSTGRES_PASSWORD','ASPNETCORE_ENVIRONMENT','ASPNETCORE_URLS','ConnectionStrings__PostgreSql','Authentication__RequireAuthenticatedUser';$old=@{};foreach($n in $vars){$old[$n]=[Environment]::GetEnvironmentVariable($n,'Process')}
try{
 $env:POSTGRES_PORT="$pgPort";$env:POSTGRES_DB='dipgovload';$env:POSTGRES_USER='dip';$env:POSTGRES_PASSWORD='dip-governance-load';Push-Location $root;try{& docker compose -p $compose up -d postgres;if($LASTEXITCODE-ne0){throw 'Postgres start failed.'};$ready=$false;for($i=0;$i-lt60;$i++){& docker compose -p $compose exec -T postgres pg_isready -U dip -d dipgovload *> $null;if($LASTEXITCODE-eq0){$ready=$true;break};Start-Sleep -Milliseconds 500};if(-not$ready){throw 'Postgres did not become ready.'};& dotnet build DevelopmentIntelligencePlatform.sln -c Release --nologo;if($LASTEXITCODE-ne0){throw 'Release build failed.'}}finally{Pop-Location}
 $env:ASPNETCORE_ENVIRONMENT='Development';$env:ASPNETCORE_URLS="http://127.0.0.1:$apiPort";$env:ConnectionStrings__PostgreSql="Host=127.0.0.1;Port=$pgPort;Database=dipgovload;Username=dip;Password=dip-governance-load";$env:Authentication__RequireAuthenticatedUser='false';$dll=Join-Path $root 'src\Dip.Api\bin\Release\net8.0\Dip.Api.dll';$api=Start-Process dotnet -ArgumentList @($dll) -WorkingDirectory $root -PassThru -WindowStyle Hidden;Wait-Http "http://127.0.0.1:$apiPort/health"
 $projectIds=@();for($i=0;$i-lt$ProjectCount;$i++){$body=@{name="Governance Load $i";repositoryUrl="https://example.invalid/load-$i";defaultBranch='main';releaseDateUtc=$null}|ConvertTo-Json;$p=Invoke-RestMethod -Method Post -Uri "http://127.0.0.1:$apiPort/api/projects" -ContentType application/json -Body $body;$projectIds+=[Guid]$p.id}
 Push-Location $root;try{foreach($pid in $projectIds){$sql=@"
INSERT INTO qa_finding_states(id,project_id,fingerprint,last_finding_id,subject_key,last_commit_sha,status,occurrences,team,workstream,ownership_source,disposition_reason,updated_by,first_seen_at_utc,last_seen_at_utc,updated_at_utc,version)
SELECT gen_random_uuid(),'$pid'::uuid,md5('${pid}:'||g::text)||md5('${pid}:x:'||g::text),gen_random_uuid(),'load:'||g,'0123456789abcdef0123456789abcdef01234567','Confirmed',1,'Load Team','Load','Rule',NULL,NULL,clock_timestamp()+(g||' microseconds')::interval,clock_timestamp()+(g||' microseconds')::interval,now(),1 FROM generate_series(1,$FindingsPerProject) g;
"@;$sql|& docker compose -p $compose exec -T postgres psql -U dip -d dipgovload -v ON_ERROR_STOP=1 *> $null;if($LASTEXITCODE-ne0){throw 'Finding seed failed.'}}}finally{Pop-Location}
 $handler=[Net.Http.HttpClientHandler]::new();$client=[Net.Http.HttpClient]::new($handler);$client.Timeout=[TimeSpan]::FromSeconds(30);$readLat=[Collections.Generic.List[double]]::new();$writeLat=[Collections.Generic.List[double]]::new();$errors=[Collections.Generic.List[string]]::new()
 # Concurrency is generated by immediately starting async HttpClient requests; PowerShell scriptblocks never run on worker threads, avoiding runspace-dependent Task.Run behavior.
 for($base=0;$base-lt$ReadRequests;$base+=$ConcurrentReaders){$pending=[Collections.ArrayList]::new();$count=[Math]::Min($ConcurrentReaders,$ReadRequests-$base);for($j=0;$j-lt$count;$j++){$index=$base+$j;$pid=$projectIds[$index%$projectIds.Count];$sw=[Diagnostics.Stopwatch]::StartNew();$task=$client.GetAsync("http://127.0.0.1:$apiPort/api/v1/qa-governance/projects/$pid/findings?pageSize=100");[void]$pending.Add([pscustomobject]@{Task=$task;Stopwatch=$sw;Kind='read';Content=$null})};Wait-HttpBatch $pending $readLat $errors}
 $targets=@();foreach($pid in $projectIds){$page=Invoke-RestMethod "http://127.0.0.1:$apiPort/api/v1/qa-governance/projects/$pid/findings?pageSize=$([Math]::Min(100,$WriteRequests))";foreach($x in $page.items){$targets+=@{projectId=$pid;fingerprint=$x.fingerprint;version=$x.version};if($targets.Count-ge$WriteRequests){break}};if($targets.Count-ge$WriteRequests){break}}
 for($base=0;$base-lt$targets.Count;$base+=$ConcurrentWriters){$pending=[Collections.ArrayList]::new();$count=[Math]::Min($ConcurrentWriters,$targets.Count-$base);for($j=0;$j-lt$count;$j++){$target=$targets[$base+$j];$payload=@{projectId=$target.projectId;fingerprint=$target.fingerprint;status='Assigned';reason='Governance formal concurrency test';expectedVersion=$target.version}|ConvertTo-Json;$content=[Net.Http.StringContent]::new($payload,[Text.Encoding]::UTF8,'application/json');$sw=[Diagnostics.Stopwatch]::StartNew();$task=$client.PostAsync("http://127.0.0.1:$apiPort/api/v1/qa-governance/findings/transition",$content);[void]$pending.Add([pscustomobject]@{Task=$task;Stopwatch=$sw;Kind='write';Content=$content})};Wait-HttpBatch $pending $writeLat $errors};$client.Dispose()
 $total=$ProjectCount*$FindingsPerProject;$readP95=Get-P95 $readLat.ToArray();$writeP95=Get-P95 $writeLat.ToArray();$errorCount=$errors.Count;$errorRate=[Math]::Round(100.0*$errorCount/[Math]::Max(1,$ReadRequests+$targets.Count),3);$passed=$readP95-lt750 -and $writeP95-lt1000 -and $errorRate-lt1
 $sha=(& git -C $root rev-parse HEAD|Out-String).Trim();$result=[ordered]@{schema='dip-governance-load-v2';sourceCommit=$sha;measuredAtUtc=[DateTimeOffset]::UtcNow.ToString('o');projects=$ProjectCount;findingStates=$total;readRequests=$ReadRequests;writeRequests=$targets.Count;concurrentReaders=$ConcurrentReaders;concurrentWriters=$ConcurrentWriters;readP95Ms=$readP95;writeP95Ms=$writeP95;errorRatePercent=$errorRate;targets=[ordered]@{readP95Ms=750;writeP95Ms=1000;errorRatePercent=1};passed=$passed;errors=@($errors|Select-Object -First 20)};$result|ConvertTo-Json -Depth 8|Set-Content (Join-Path $out 'governance-load-results.json') -Encoding UTF8;if(!$passed){throw "Governance load test failed. read p95=$readP95 write p95=$writeP95 error=$errorRate%"};@('GOVERNANCE LOAD PASS',"Commit=$sha","FindingStates=$total","ReadP95Ms=$readP95","WriteP95Ms=$writeP95","ErrorRatePercent=$errorRate")|Set-Content (Join-Path $out 'GOVERNANCE_LOAD_PASS.txt') -Encoding UTF8
}finally{if($api -and !$api.HasExited){Stop-Process $api.Id -Force -ErrorAction SilentlyContinue};Push-Location $root;try{& docker compose -p $compose down -v --remove-orphans *> $null}catch{}finally{Pop-Location};foreach($n in $vars){[Environment]::SetEnvironmentVariable($n,$old[$n],'Process')}}
